import { describe, expect, test, beforeAll, afterAll } from "bun:test";
import { validateYamlContent, validateYamlFile } from "./yaml-validator";
import { mkdir, rm, writeFile } from "node:fs/promises";
import { join } from "node:path";

describe("yaml-validator", () => {
  describe("validateYamlContent", () => {
    test("returns success for valid YAML", () => {
      const content = "key: value";
      const result = validateYamlContent(content);

      expect(result.success).toBe(true);
      expect(result.error).toBeUndefined();
      expect(result.line).toBeUndefined();
      expect(result.column).toBeUndefined();
    });

    test("returns success for empty content", () => {
      const content = "";
      const result = validateYamlContent(content);

      expect(result.success).toBe(true);
      expect(result.error).toBeUndefined();
    });

    test("returns error with line number for invalid YAML", () => {
      const content = `valid: yaml
  invalid indentation`;
      const result = validateYamlContent(content);

      expect(result.success).toBe(false);
      expect(result.error).toBeDefined();
      expect(result.line).toBeDefined();
      expect(typeof result.line).toBe("number");
    });

    test("returns error with column number for invalid YAML", () => {
      const content = `key: [unclosed`;
      const result = validateYamlContent(content);

      expect(result.success).toBe(false);
      expect(result.error).toBeDefined();
      expect(result.column).toBeDefined();
      expect(typeof result.column).toBe("number");
    });

    test("handles YAML with comments", () => {
      const content = `# This is a comment
key: value
# Another comment
nested:
  child: data # inline comment`;
      const result = validateYamlContent(content);

      expect(result.success).toBe(true);
      expect(result.error).toBeUndefined();
    });

    test("handles multi-document YAML", () => {
      const content = `---
document: one
---
document: two
---
document: three`;
      const result = validateYamlContent(content);

      expect(result.success).toBe(true);
      expect(result.error).toBeUndefined();
    });
  });

  describe("validateYamlFile", () => {
    const testDir = join(import.meta.dir, ".test-temp");
    const validYamlPath = join(testDir, "valid.yaml");
    const invalidYamlPath = join(testDir, "invalid.yaml");
    const nonExistentPath = join(testDir, "does-not-exist.yaml");

    beforeAll(async () => {
      await mkdir(testDir, { recursive: true });
      await writeFile(validYamlPath, "key: value\nlist:\n  - item1\n  - item2");
      await writeFile(invalidYamlPath, "key: [unclosed");
    });

    afterAll(async () => {
      await rm(testDir, { recursive: true, force: true });
    });

    test("returns success for valid YAML file", async () => {
      const result = await validateYamlFile(validYamlPath);

      expect(result.success).toBe(true);
      expect(result.filepath).toBe(validYamlPath);
      expect(result.error).toBeUndefined();
    });

    test("returns error for non-existent file", async () => {
      const result = await validateYamlFile(nonExistentPath);

      expect(result.success).toBe(false);
      expect(result.filepath).toBe(nonExistentPath);
      expect(result.error).toBe("File not found");
    });

    test("returns error for invalid YAML file", async () => {
      const result = await validateYamlFile(invalidYamlPath);

      expect(result.success).toBe(false);
      expect(result.filepath).toBe(invalidYamlPath);
      expect(result.error).toBeDefined();
      expect(result.line).toBeDefined();
    });
  });
});

