/**
 * YAML validation module for syntax checking.
 */

import yaml from "js-yaml";

/**
 * Result of YAML validation operation
 */
export interface ValidationResult {
  /** Whether validation succeeded */
  success: boolean;
  /** File path that was validated */
  filepath: string;
  /** Error message if validation failed */
  error?: string;
  /** Line number where error occurred (1-indexed) */
  line?: number;
  /** Column number where error occurred (1-indexed) */
  column?: number;
}

/**
 * Validates YAML content string for syntax correctness.
 * Useful for testing without file I/O.
 *
 * @param content - YAML content to validate
 * @param filepath - Optional filepath for error reporting
 * @returns ValidationResult indicating success or failure with details
 */
export function validateYamlContent(
  content: string,
  filepath: string = ""
): ValidationResult {
  try {
    yaml.load(content);
    return {
      success: true,
      filepath,
    };
  } catch (err) {
    if (err instanceof yaml.YAMLException) {
      const result: ValidationResult = {
        success: false,
        filepath,
        error: err.reason || err.message,
      };

      if (err.mark) {
        result.line = err.mark.line + 1;
        result.column = err.mark.column + 1;
      }

      return result;
    }

    return {
      success: false,
      filepath,
      error: err instanceof Error ? err.message : String(err),
    };
  }
}

/**
 * Validates a YAML file for syntax correctness.
 *
 * @param filepath - Path to the YAML file to validate
 * @returns ValidationResult indicating success or failure with details
 */
export async function validateYamlFile(
  filepath: string
): Promise<ValidationResult> {
  try {
    const file = Bun.file(filepath);
    const exists = await file.exists();

    if (!exists) {
      return {
        success: false,
        filepath,
        error: "File not found",
      };
    }

    const content = await file.text();
    return validateYamlContent(content, filepath);
  } catch (err) {
    return {
      success: false,
      filepath,
      error: err instanceof Error ? err.message : String(err),
    };
  }
}

