        "file_path": "/private/tmp/rp1-evals/0c034016/workspace/.rp1/work/worktrees/feature-yaml-validator-command/src/yaml/validator.ts",
        "content": "/**\n * YAML syntax validator module.\n *\n * Validates YAML files for common syntax errors without external dependencies.\n * Note: This is a syntax validator, not a full YAML parser. It checks for\n * common structural issues but does not implement the complete YAML specification.\n *\n * Limitations:\n * - Does not validate against YAML schema\n * - May not catch all edge cases of YAML 1.2 specification\n * - Complex anchors and aliases have limited validation\n * - Multi-document support is limited\n */\n\nimport type { ValidationError, ValidationResult, ErrorType } from \"./types\";\n\n/**\n * Validate a YAML file for syntax correctness.\n * @param filePath - Path to the YAML file to validate\n * @returns ValidationResult with validation status and any errors\n */\nexport async function validateYamlFile(\n  filePath: string\n): Promise<ValidationResult> {\n  try {\n    const file = Bun.file(filePath);\n    const exists = await file.exists();\n\n    if (!exists) {\n      return {\n        valid: false,\n        filePath,\n        errors: [\n          {\n            line: 0,\n            message: `File not found: ${filePath}`,\n            type: \"FileNotFound\",\n          },\n        ],\n      };\n    }\n\n    const content = await file.text();\n    return validateYamlContent(content, filePath);\n  } catch (error) {\n    const errorMessage =\n      error instanceof Error ? error.message : \"Unknown error\";\n    return {\n      valid: false,\n      filePath,\n      errors: [\n        {\n          line: 0,\n          message: `Failed to read file: ${errorMessage}`,\n          type: \"FileReadError\",\n        },\n      ],\n    };\n  }\n}\n\n/**\n * Validate YAML content string for syntax correctness.\n * @param content - YAML content to validate\n * @param filePath - Optional file path for error reporting\n * @returns ValidationResult with validation status and any errors\n */\nexport function validateYamlContent(\n  content: string,\n  filePath: string = \"\"\n): ValidationResult {\n  const errors: ValidationError[] = [];\n\n  // Check for empty content\n  if (!content || content.trim().length === 0) {\n    return {\n      valid: false,\n      filePath,\n      errors: [\n        {\n          line: 1,\n          message: \"File is empty or contains only whitespace\",\n          type: \"EmptyFile\",\n        },\n      ],\n    };\n  }\n\n  const lines = content.split(\"\\n\");\n\n  // Track indentation levels for consistency checking\n  let baseIndentUnit: number | null = null;\n\n  // Track keys at each indentation level for duplicate detection\n  const keysByIndent: Map<number, Set<string>> = new Map();\n\n  // Track quote state for unclosed quote detection\n  let inMultilineString = false;\n  let multilineStringIndent = 0;\n  let multilineStringStartLine = 0;\n\n  for (let i = 0; i < lines.length; i++) {\n    const lineNum = i + 1;\n    const line = lines[i];\n\n    // Skip empty lines\n    if (line.trim() === \"\") {\n      continue;\n    }\n\n    // Skip comment-only lines\n    if (line.trim().startsWith(\"#\")) {\n      continue;\n    }\n\n    // Handle multiline string content (| or >)\n    if (inMultilineString) {\n      const currentIndent = getIndentation(line);\n      if (currentIndent > multilineStringIndent || line.trim() === \"\") {\n        continue;\n      } else {\n        inMultilineString = false;\n      }\n    }\n\n    // Check for tab indentation\n    const tabError = checkTabIndentation(line, lineNum);\n    if (tabError) {\n      errors.push(tabError);\n      continue;\n    }\n\n    // Check indentation consistency\n    const indentError = checkIndentationConsistency(\n      line,\n      lineNum,\n      baseIndentUnit\n    );\n    if (indentError.error) {\n      errors.push(indentError.error);\n    }\n    if (indentError.baseUnit !== null && baseIndentUnit === null) {\n      baseIndentUnit = indentError.baseUnit;\n    }\n\n    // Check for unclosed quotes\n    const quoteError = checkQuotes(line, lineNum);\n    if (quoteError) {\n      errors.push(quoteError);\n      continue;\n    }\n\n    // Check for multiline string indicators\n    const multilineCheck = checkMultilineIndicator(line, lineNum);\n    if (multilineCheck.isMultiline) {\n      inMultilineString = true;\n      multilineStringIndent = getIndentation(line);\n      multilineStringStartLine = lineNum;\n    }\n\n    // Check list syntax\n    const listError = checkListSyntax(line, lineNum);\n    if (listError) {\n      errors.push(listError);\n      continue;\n    }\n\n    // Check key-value syntax and track keys for duplicates\n    const kvResult = checkKeyValueSyntax(line, lineNum);\n    if (kvResult.error) {\n      errors.push(kvResult.error);\n      continue;\n    }\n\n    // Check for duplicate keys at the same indentation level\n    if (kvResult.key) {\n      const currentIndent = getIndentation(line);\n      const duplicateError = checkDuplicateKey(\n        kvResult.key,\n        currentIndent,\n        lineNum,\n        keysByIndent\n      );\n      if (duplicateError) {\n        errors.push(duplicateError);\n      }\n    }\n\n    // Reset keys for lower indentation levels (scope exit)\n    const currentIndent = getIndentation(line);\n    for (const [indent] of keysByIndent) {\n      if (indent > currentIndent) {\n        keysByIndent.delete(indent);\n      }\n    }\n  }\n\n  return {\n    valid: errors.length === 0,\n    filePath,\n    errors,\n  };\n}\n\n/**\n * Get the number of leading spaces in a line.\n */\nfunction getIndentation(line: string): number {\n  const match = line.match(/^( *)/);\n  return match ? match[1].length : 0;\n}\n\n/**\n * Check if line uses tabs for indentation.\n */\nfunction checkTabIndentation(\n  line: string,\n  lineNum: number\n): ValidationError | null {\n  const leadingWhitespace = line.match(/^(\\s*)/);\n  if (leadingWhitespace && leadingWhitespace[1].includes(\"\\t\")) {\n    const tabPosition = leadingWhitespace[1].indexOf(\"\\t\");\n    return {\n      line: lineNum,\n      column: tabPosition + 1,\n      message: \"Tabs are not allowed for indentation in YAML\",\n      type: \"IndentationError\",\n    };\n  }\n  return null;\n}\n\n/**\n * Check indentation consistency with established base unit.\n */\nfunction checkIndentationConsistency(\n  line: string,\n  lineNum: number,\n  baseIndentUnit: number | null\n): { error: ValidationError | null; baseUnit: number | null } {\n  const indent = getIndentation(line);\n  const trimmedLine = line.trim();\n\n  // Skip if no indentation\n  if (indent === 0) {\n    return { error: null, baseUnit: null };\n  }\n\n  // Determine base indent unit if not yet established\n  if (baseIndentUnit === null) {\n    // Common indent units are 2 or 4 spaces\n    if (indent > 0) {\n      return { error: null, baseUnit: indent };\n    }\n  }\n\n  // Check if indentation is a multiple of the base unit\n  if (baseIndentUnit !== null && indent % baseIndentUnit !== 0) {\n    // Allow for list items which may have different indentation\n    if (!trimmedLine.startsWith(\"-\")) {\n      return {\n        error: {\n          line: lineNum,\n          column: 1,\n          message: `Inconsistent indentation: expected multiple of ${baseIndentUnit} spaces, found ${indent}`,\n          type: \"IndentationError\",\n        },\n        baseUnit: null,\n      };\n    }\n  }\n\n  return { error: null, baseUnit: null };\n}\n\n/**\n * Check for unclosed quotes in a line.\n */\nfunction checkQuotes(line: string, lineNum: number): ValidationError | null {\n  const trimmed = line.trim();\n\n  // Skip comment lines\n  if (trimmed.startsWith(\"#\")) {\n    return null;\n  }\n\n  // Skip lines that are just list markers or multiline indicators\n  if (trimmed === \"-\" || trimmed === \"|\" || trimmed === \">\" || trimmed === \"|+\" || trimmed === \">-\") {\n    return null;\n  }\n\n  // Find all quote characters and check if they're balanced\n  let inSingleQuote = false;\n  let inDoubleQuote = false;\n  let singleQuoteStart = -1;\n  let doubleQuoteStart = -1;\n\n  for (let i = 0; i < trimmed.length; i++) {\n    const char = trimmed[i];\n    const prevChar = i > 0 ? trimmed[i - 1] : \"\";\n\n    // Skip escaped quotes\n    if (prevChar === \"\\\\\") {\n      continue;\n    }\n\n    // Check for comment start outside of quotes\n    if (char === \"#\" && !inSingleQuote && !inDoubleQuote) {\n      break;\n    }\n\n    if (char === \"'\" && !inDoubleQuote) {\n      if (inSingleQuote) {\n        inSingleQuote = false;\n        singleQuoteStart = -1;\n      } else {\n        inSingleQuote = true;\n        singleQuoteStart = i;\n      }\n    } else if (char === '\"' && !inSingleQuote) {\n      if (inDoubleQuote) {\n        inDoubleQuote = false;\n        doubleQuoteStart = -1;\n      } else {\n        inDoubleQuote = true;\n        doubleQuoteStart = i;\n      }\n    }\n  }\n\n  if (inSingleQuote) {\n    return {\n      line: lineNum,\n      column: singleQuoteStart + getIndentation(line) + 1,\n      message: \"Unclosed single quote\",\n      type: \"QuoteError\",\n    };\n  }\n\n  if (inDoubleQuote) {\n    return {\n      line: lineNum,\n      column: doubleQuoteStart + getIndentation(line) + 1,\n      message: \"Unclosed double quote\",\n      type: \"QuoteError\",\n    };\n  }\n\n  return null;\n}\n\n/**\n * Check for multiline string indicators (| or >).\n */\nfunction checkMultilineIndicator(\n  line: string,\n  lineNum: number\n): { isMultiline: boolean; error: ValidationError | null } {\n  const trimmed = line.trim();\n\n  // Check if line ends with multiline indicator\n  const multilineMatch = trimmed.match(/:\\s*([|>][+-]?)(\\s*#.*)?$/);\n  if (multilineMatch) {\n    return { isMultiline: true, error: null };\n  }\n\n  return { isMultiline: false, error: null };\n}\n\n/**\n * Check list syntax validity.\n */\nfunction checkListSyntax(\n  line: string,\n  lineNum: number\n): ValidationError | null {\n  const trimmed = line.trim();\n\n  // Check for list items\n  if (trimmed.startsWith(\"-\")) {\n    // Valid list syntax: \"- value\" or \"-\" alone for nested structures\n    if (trimmed === \"-\") {\n      return null;\n    }\n\n    // Check for proper spacing after dash\n    if (trimmed.length > 1 && trimmed[1] !== \" \") {\n      // Allow for \"---\" document separator\n      if (trimmed === \"---\") {\n        return null;\n      }\n      return {\n        line: lineNum,\n        column: getIndentation(line) + 2,\n        message: \"List item must have a space after the dash\",\n        type: \"ListError\",\n      };\n    }\n  }\n\n  return null;\n}\n\n/**\n * Check key-value syntax validity.\n */\nfunction checkKeyValueSyntax(\n  line: string,\n  lineNum: number\n): { error: ValidationError | null; key: string | null } {\n  const trimmed = line.trim();\n\n  // Skip empty lines, comments, list items, and document separators\n  if (\n    trimmed === \"\" ||\n    trimmed.startsWith(\"#\") ||\n    trimmed.startsWith(\"-\") ||\n    trimmed === \"---\" ||\n    trimmed === \"...\"\n  ) {\n    return { error: null, key: null };\n  }\n\n  // Check for colon in line (key-value pair)\n  const colonIndex = findKeyColonIndex(trimmed);\n\n  if (colonIndex === -1) {\n    // No colon found - might be a value continuation or invalid syntax\n    // If it's just a plain value (no special characters at start), it might be invalid\n    if (!trimmed.startsWith(\"|\") && !trimmed.startsWith(\">\")) {\n      // Could be a flow sequence or mapping\n      if (trimmed.startsWith(\"[\") || trimmed.startsWith(\"{\")) {\n        // Basic check for balanced brackets\n        const bracketError = checkBalancedBrackets(trimmed, lineNum, line);\n        if (bracketError) {\n          return { error: bracketError, key: null };\n        }\n        return { error: null, key: null };\n      }\n\n      // Allow plain scalar values that might be part of multiline or flow content\n      return { error: null, key: null };\n    }\n    return { error: null, key: null };\n  }\n\n  // Extract the key\n  const key = trimmed.substring(0, colonIndex).trim();\n\n  // Check for empty key\n  if (key === \"\") {\n    return {\n      error: {\n        line: lineNum,\n        column: getIndentation(line) + 1,\n        message: \"Empty key in key-value pair\",\n        type: \"SyntaxError\",\n      },\n      key: null,\n    };\n  }\n\n  // Check for invalid characters in unquoted key\n  if (!key.startsWith('\"') && !key.startsWith(\"'\")) {\n    // Unquoted keys should not contain certain characters\n    if (key.includes(\": \") || key.includes(\" #\")) {\n      return {\n        error: {\n          line: lineNum,\n          column: getIndentation(line) + 1,\n          message: \"Invalid characters in unquoted key\",\n          type: \"SyntaxError\",\n        },\n        key: null,\n      };\n    }\n  }\n\n  return { error: null, key };\n}\n\n/**\n * Find the index of the colon that separates key from value,\n * ignoring colons inside quotes.\n */\nfunction findKeyColonIndex(line: string): number {\n  let inSingleQuote = false;\n  let inDoubleQuote = false;\n\n  for (let i = 0; i < line.length; i++) {\n    const char = line[i];\n    const prevChar = i > 0 ? line[i - 1] : \"\";\n\n    // Skip escaped characters\n    if (prevChar === \"\\\\\") {\n      continue;\n    }\n\n    if (char === \"'\" && !inDoubleQuote) {\n      inSingleQuote = !inSingleQuote;\n    } else if (char === '\"' && !inSingleQuote) {\n      inDoubleQuote = !inDoubleQuote;\n    } else if (char === \":\" && !inSingleQuote && !inDoubleQuote) {\n      // Check if followed by space, newline, or end of line (valid key-value separator)\n      const nextChar = i < line.length - 1 ? line[i + 1] : \"\";\n      if (nextChar === \" \" || nextChar === \"\" || nextChar === \"\\t\") {\n        return i;\n      }\n      // Also accept colon at end of line\n      if (i === line.length - 1) {\n        return i;\n      }\n    }\n  }\n\n  return -1;\n}\n\n/**\n * Check for balanced brackets in flow syntax.\n */\nfunction checkBalancedBrackets(\n  line: string,\n  lineNum: number,\n  fullLine: string\n): ValidationError | null {\n  let squareBrackets = 0;\n  let curlyBraces = 0;\n  let inSingleQuote = false;\n  let inDoubleQuote = false;\n\n  for (let i = 0; i < line.length; i++) {\n    const char = line[i];\n    const prevChar = i > 0 ? line[i - 1] : \"\";\n\n    if (prevChar === \"\\\\\") {\n      continue;\n    }\n\n    if (char === \"'\" && !inDoubleQuote) {\n      inSingleQuote = !inSingleQuote;\n    } else if (char === '\"' && !inSingleQuote) {\n      inDoubleQuote = !inDoubleQuote;\n    } else if (!inSingleQuote && !inDoubleQuote) {\n      if (char === \"[\") squareBrackets++;\n      else if (char === \"]\") squareBrackets--;\n      else if (char === \"{\") curlyBraces++;\n      else if (char === \"}\") curlyBraces--;\n    }\n  }\n\n  if (squareBrackets !== 0) {\n    return {\n      line: lineNum,\n      column: getIndentation(fullLine) + 1,\n      message:\n        squareBrackets > 0 ? \"Unclosed square bracket\" : \"Extra closing square bracket\",\n      type: \"SyntaxError\",\n    };\n  }\n\n  if (curlyBraces !== 0) {\n    return {\n      line: lineNum,\n      column: getIndentation(fullLine) + 1,\n      message:\n        curlyBraces > 0 ? \"Unclosed curly brace\" : \"Extra closing curly brace\",\n      type: \"SyntaxError\",\n    };\n  }\n\n  return null;\n}\n\n/**\n * Check for duplicate keys at the same indentation level.\n */\nfunction checkDuplicateKey(\n  key: string,\n  indent: number,\n  lineNum: number,\n  keysByIndent: Map<number, Set<string>>\n): ValidationError | null {\n  if (!keysByIndent.has(indent)) {\n    keysByIndent.set(indent, new Set());\n  }\n\n  const keysAtLevel = keysByIndent.get(indent)!;\n\n  if (keysAtLevel.has(key)) {\n    return {\n      line: lineNum,\n      column: 1,\n      message: `Duplicate key \"${key}\" at the same level`,\n      type: \"DuplicateKeyError\",\n    };\n  }\n\n  keysAtLevel.add(key);\n  return null;\n}\n"
      },
      "source": "assistant"
