n      const indentDiff = currentIndent - parentIndent;\n\n      // Standard YAML indentation is typically 2 spaces\n      // But odd indentation at non-standard positions is problematic\n      if (indentDiff !== 2 && indentDiff !== 0 && currentIndent !== parentIndent) {\n        // Check if this is a valid indent level we've seen before\n        const validIndent = indentStack.includes(currentIndent);\n        if (!validIndent && indentDiff !== 2) {\n          errors.push({\n            line: lineNum,\n            message: `Inconsistent indentation: expected ${parentIndent + 2} spaces, got ${currentIndent}`,\n            type: 'indentation'\n          });\n        }\n      }\n\n      indentStack.push(currentIndent);\n    } else {\n      // Reset to root level\n      indentStack.length = 1;\n      indentStack[0] = 0;\n    }\n\n    // Check for unclosed quotes\n    const unescapedSingleQuotes = trimmedLine.replace(/\\\\'/g, '').match(/'/g) || [];\n    const unescapedDoubleQuotes = trimmedLine.replace(/\\\\\"/g, '').match(/\"/g) || [];\n\n    if (unescapedSingleQuotes.length % 2 !== 0) {\n      errors.push({\n        line: lineNum,\n        message: 'Unclosed single quote',\n        type: 'unclosed_quote'\n      });\n    }\n\n    if (unescapedDoubleQuotes.length % 2 !== 0) {\n      errors.push({\n        line: lineNum,\n        message: 'Unclosed double quote',\n        type: 'unclosed_quote'\n      });\n    }\n\n    // Check key-value syntax\n    if (!trimmedLine.startsWith('-') && !trimmedLine.startsWith('#') &&\n        !trimmedLine.startsWith('|') && !trimmedLine.startsWith('>')) {\n      const colonIndex = trimmedLine.indexOf(':');\n\n      if (colonIndex > 0) {\n        const afterColon = trimmedLine.substring(colonIndex + 1);\n\n        // Value after colon should have space if not empty\n        if (afterColon !== '' && !afterColon.startsWith(' ') && !afterColon.startsWith('\\t')) {\n          errors.push({\n            line: lineNum,\n            message: 'Missing space after colon in key-value pair',\n            type: 'invalid_key_value'\n          });\n        }\n\n        // Check for invalid key characters\n        const key = trimmedLine.substring(0, colonIndex);\n        if (key.match(/^[\\[\\]{},]/)) {\n          errors.push({\n            line: lineNum,\n            message: 'Invalid key: starts with special character',\n            type: 'invalid_key_value'\n          });\n        }\n      }\n    }\n\n    // Check list formatting\n    if (trimmedLine.startsWith('-')) {\n      if (trimmedLine.length > 1 && trimmedLine[1] !== ' ' && trimmedLine[1] !== '\\t') {\n        errors.push({\n          line: lineNum,\n          message: 'List item should have space after dash',\n          type: 'list_format'\n        });\n      }\n    }\n  }\n\n  return {\n    valid: errors.length === 0,\n    errors\n  };\n}\n\n// ==========================================\n// REFERENCE: JS-YAML PARSER\n// ==========================================\n\nfunction jsYamlValidate(content: string): { valid: boolean; error?: string } {\n  try {\n    parseYaml(content);\n    return { valid: true };\n  } catch (e: any) {\n    return { valid: false, error: e.message };\n  }\n}\n\n// ==========================================\n// COMPREHENSIVE TEST CASES\n// ==========================================\n\ninterface TestCase {\n  name: string;\n  yaml: string;\n  category: string;\n}\n\nconst testCases: TestCase[] = [\n  // VALID YAML\n  { name: 'Valid - basic', category: 'valid', yaml: `name: test\\nversion: 1.0.0` },\n  { name: 'Valid - nested', category: 'valid', yaml: `config:\\n  db:\\n    host: localhost` },\n  { name: 'Valid - list', category: 'valid', yaml: `items:\\n  - one\\n  - two\\n  - three` },\n  { name: 'Valid - empty', category: 'valid', yaml: `` },\n  { name: 'Valid - comments only', category: 'valid', yaml: `# comment\\n# another` },\n  { name: 'Valid - quoted colon', category: 'valid', yaml: `url: \"http://example.com\"` },\n  { name: 'Valid - multiline', category: 'valid', yaml: `desc: |\\n  line1\\n  line2` },\n  { name: 'Valid - flow seq', category: 'valid', yaml: `items: [a, b, c]` },\n  { name: 'Valid - flow map', category: 'valid', yaml: `person: {name: John, age: 30}` },\n  { name: 'Valid - deep nest', category: 'valid', yaml: `a:\\n  b:\\n    c:\\n      d: value` },\n\n  // INDENTATION ERRORS\n  { name: 'Indent - inconsistent (3 spaces)', category: 'indentation', yaml: `config:\\n  name: test\\n   version: 1.0` },\n  { name: 'Indent - tabs', category: 'indentation', yaml: `config:\\n\\tname: test` },\n  { name: 'Indent - mixed tabs spaces', category: 'indentation', yaml: `config:\\n  \\tname: test` },\n  { name: 'Indent - wrong level return', category: 'indentation', yaml: `a:\\n  b: 1\\n c: 2` },\n\n  // QUOTE ERRORS\n  { name: 'Quote - unclosed single', category: 'quote', yaml: `name: 'unterminated` },\n  { name: 'Quote - unclosed double', category: 'quote', yaml: `name: \"unterminated` },\n  { name: 'Quote - unmatched', category: 'quote', yaml: `name: \"value'` },\n\n  // KEY-VALUE ERRORS\n  { name: 'KV - no space after colon', category: 'key_value', yaml: `name:value` },\n  { name: 'KV - special char key', category: 'key_value', yaml: `[invalid: key` },\n\n  // LIST ERRORS\n  { name: 'List - no space after dash', category: 'list', yaml: `items:\\n  -one\\n  -two` },\n\n  // EDGE CASES (Tricky valid YAML)\n  { name: 'Edge - colon in unquoted value', category: 'edge', yaml: `time: 12:30:00` },\n  { name: 'Edge - special chars in quoted', category: 'edge', yaml: `text: \"{ brackets }\"` },\n  { name: 'Edge - anchor reference', category: 'edge', yaml: `base: &base\\n  name: test\\nderived:\\n  <<: *base` },\n  { name: 'Edge - null values', category: 'edge', yaml: `empty:\\nnull_val: null` },\n  { name: 'Edge - boolean values', category: 'edge', yaml: `flag1: true\\nflag2: false\\nflag3: yes\\nflag4: no` },\n];\n\n// ==========================================\n// RUN COMPREHENSIVE COMPARISON\n// ==========================================\n\nconsole.log('='.repeat(70));\nconsole.log('COMPREHENSIVE HYPOTHESIS EXPERIMENT: HYP-001');\nconsole.log('Custom YAML Validator vs js-yaml Parser');\nconsole.log('='.repeat(70));\nconsole.log();\n\ninterface ComparisonResult {\n  name: string;\n  category: string;\n  jsYamlValid: boolean;\n  customValid: boolean;\n  match: boolean;\n  jsYamlError?: string;\n  customErrors: ValidationError[];\n}\n\nconst results: ComparisonResult[] = [];\nlet matches = 0;\nlet falsePositives: ComparisonResult[] = [];\nlet falseNegatives: ComparisonResult[] = [];\n\nfor (const testCase of testCases) {\n  const jsYamlResult = jsYamlValidate(testCase.yaml);\n  const customResult = customYamlValidator(testCase.yaml);\n\n  const comparison: ComparisonResult = {\n    name: testCase.name,\n    category: testCase.category,\n    jsYamlValid: jsYamlResult.valid,\n    customValid: customResult.valid,\n    match: jsYamlResult.valid === customResult.valid,\n    jsYamlError: jsYamlResult.error,\n    customErrors: customResult.errors\n  };\n\n  results.push(comparison);\n\n  if (comparison.match) {\n    matches++;\n    console.log(`[MATCH] ${testCase.name}`);\n    console.log(`        Both: ${jsYamlResult.valid ? 'VALID' : 'INVALID'}`);\n  } else {\n    if (customResult.valid && !jsYamlResult.valid) {\n      // Custom says valid, js-yaml says invalid = FALSE NEGATIVE\n      falseNegatives.push(comparison);\n      console.log(`[MISMATCH - FALSE NEGATIVE] ${testCase.name}`);\n      console.log(`        js-yaml: INVALID - ${jsYamlResult.error}`);\n      console.log(`        custom:  VALID (missed error!)`);\n    } else {\n      // Custom says invalid, js-yaml says valid = FALSE POSITIVE\n      falsePositives.push(comparison);\n      console.log(`[MISMATCH - FALSE POSITIVE] ${testCase.name}`);\n      console.log(`        js-yaml: VALID`);\n      console.log(`        custom:  INVALID - ${customResult.errors.map(e => e.message).join(', ')}`);\n    }