n    console.log(`     [WARN] ${customResult.warnings.map(w => w.message).join(', ')}`);\n  }\n}\n\nconsole.log();\nconsole.log('='.repeat(70));\nconsole.log('METRICS');\nconsole.log('='.repeat(70));\n\nconst total = testCases.length;\nconst accuracy = (truePositives + trueNegatives) / total;\nconst precision = truePositives / (truePositives + falsePositives) || 0;\nconst recall = truePositives / (truePositives + falseNegatives) || 0;\nconst f1 = 2 * (precision * recall) / (precision + recall) || 0;\n\nconsole.log(`Total Test Cases: ${total}`);\nconsole.log();\nconsole.log(`True Positives (both invalid):  ${truePositives}`);\nconsole.log(`True Negatives (both valid):    ${trueNegatives}`);\nconsole.log(`False Positives (false alarm):  ${falsePositives}`);\nconsole.log(`False Negatives (missed error): ${falseNegatives}`);\nconsole.log();\nconsole.log(`Accuracy:  ${(accuracy * 100).toFixed(1)}%`);\nconsole.log(`Precision: ${(precision * 100).toFixed(1)}%`);\nconsole.log(`Recall:    ${(recall * 100).toFixed(1)}%`);\nconsole.log(`F1 Score:  ${(f1 * 100).toFixed(1)}%`);\n\nconsole.log();\nconsole.log('='.repeat(70));\nconsole.log('DETAILED FINDINGS');\nconsole.log('='.repeat(70));\n\nif (fnList.length > 0) {\n  console.log();\n  console.log('FALSE NEGATIVES (CRITICAL - missed syntax errors):');\n  fnList.forEach(fn => console.log(`  - ${fn}`));\n}\n\nif (fpList.length > 0) {\n  console.log();\n  console.log('FALSE POSITIVES (incorrectly flagged valid YAML):');\n  fpList.forEach(fp => console.log(`  - ${fp}`));\n}\n\nconsole.log();\nconsole.log('='.repeat(70));\nconsole.log('HYPOTHESIS VERDICT');\nconsole.log('='.repeat(70));\n\n// Criteria:\n// CONFIRM: Correctly identifies indentation errors, unclosed quotes, invalid key-value, empty files, list formatting\n// REJECT: Fails to detect obvious errors OR produces false positives on valid YAML\n\nconst criticalErrorsMissed = falseNegatives;\nconst hasFalsePositives = falsePositives > 0;\n\nconsole.log();\nif (criticalErrors