        "content": "/**\n * Type definitions for the YAML validator module.\n */\n\n/**\n * Types of validation errors that can be detected.\n */\nexport type ErrorType =\n  | \"FileNotFound\"\n  | \"FileReadError\"\n  | \"EmptyFile\"\n  | \"IndentationError\"\n  | \"SyntaxError\"\n  | \"QuoteError\"\n  | \"ListError\"\n  | \"DuplicateKeyError\";\n\n/**\n * Represents a single validation error with location information.\n */\nexport interface ValidationError {\n  /** Line number where the error was detected (1-indexed) */\n  line: number;\n  /** Column number where the error was detected (1-indexed, optional) */\n  column?: number;\n  /** Human-readable error message */\n  message: string;\n  /** Type of the validation error */\n  type: ErrorType;\n}\n\n/**\n * Result of validating a YAML file or content.\n */\nexport interface ValidationResult {\n  /** Whether the YAML is valid */\n  valid: boolean;\n  /** Path to the validated file (empty string if validating content directly) */\n  filePath: string;\n  /** List of validation errors found (empty if valid) */\n  errors: ValidationError[];\n}\n"
