        "content": "/**\n * CLI entry point for YAML validation command.\n *\n * Usage: bun run validate-yaml <filepath>\n *\n * Exit codes:\n *   0 - Validation successful\n *   1 - Validation failed or error occurred\n */\n\nimport { validateYamlFile } from \"./yaml/validator\";\n\nasync function main(): Promise<void> {\n  const args = process.argv.slice(2);\n\n  if (args.length === 0) {\n    console.error(\"Error: No file path provided\");\n    console.error(\"Usage: bun run validate-yaml <filepath>\");\n    process.exit(1);\n  }\n\n  const filePath = args[0];\n  const result = await validateYamlFile(filePath);\n\n  if (result.valid) {\n    console.log(`Valid: ${result.filePath}`);\n    process.exit(0);\n  }\n\n  if (\n    result.errors.length > 0 &&\n    result.errors[0].type === \"FileNotFound\"\n  ) {\n    console.error(`Error: File not found: ${filePath}`);\n    process.exit(1);\n  }\n\n  if (\n    result.errors.length > 0 &&\n    result.errors[0].type === \"FileReadError\"\n  ) {\n    console.error(`Error: ${result.errors[0].message}`);\n    process.exit(1);\n  }\n\n  console.log(`Invalid: ${result.filePath}`);\n  for (const error of result.errors) {\n    const lineInfo = error.line > 0 ? `Line ${error.line}: ` : \"\";\n    console.log(`  ${lineInfo}${error.message}`);\n  }\n  process.exit(1);\n}\n\nmain();\n"
