        "content": "/**\n * HYPOTHESIS EXPERIMENT: HYP-001\n * Testing whether a custom YAML syntax validator can adequately detect\n * common syntax errors without external parsing libraries\n *\n * This code is DISPOSABLE - for validation purposes only\n */\n\n// ==========================================\n// CUSTOM YAML VALIDATOR (No External Libraries)\n// ==========================================\n\ninterface ValidationError {\n  line: number;\n  message: string;\n  type: string;\n}\n\ninterface ValidationResult {\n  valid: boolean;\n  errors: ValidationError[];\n}\n\nfunction customYamlValidator(content: string): ValidationResult {\n  const errors: ValidationError[] = [];\n  const lines = content.split('\\n');\n\n  // Track indentation levels\n  let prevIndent = 0;\n  let inMultilineString = false;\n  let multilineQuoteChar: string | null = null;\n\n  for (let i = 0; i < lines.length; i++) {\n    const lineNum = i + 1;\n    const line = lines[i];\n    const trimmedLine = line.trimStart();\n\n    // Skip empty lines and comments\n    if (trimmedLine === '' || trimmedLine.startsWith('#')) {\n      continue;\n    }\n\n    // Calculate indentation\n    const currentIndent = line.length - trimmedLine.length;\n\n    // Check 1: Indentation errors - must use consistent spacing\n    if (currentIndent % 2 !== 0 && !line.includes('\\t')) {\n      // Warning: odd indentation (not strictly an error but suspicious)\n    }\n\n    // Check for tabs (YAML spec prefers spaces)\n    if (line.includes('\\t')) {\n      errors.push({\n        line: lineNum,\n        message: 'Tab character found - YAML recommends spaces for indentation',\n        type: 'indentation'\n      });\n    }\n\n    // Check 2: Unclosed quotes\n    const singleQuotes = (trimmedLine.match(/'/g) || []).length;\n    const doubleQuotes = (trimmedLine.match(/\"/g) || []).length;\n\n    // Check for unclosed single quotes (ignoring escaped quotes)\n    const unescapedSingleQuotes = trimmedLine.replace(/\\\\'/g, '').match(/'/g) || [];\n    const unescapedDoubleQuotes = trimmedLine.replace(/\\\\\"/g, '').match(/\"/g) || [];\n\n    if (unescapedSingleQuotes.length % 2 !== 0) {\n      errors.push({\n        line: lineNum,\n        message: 'Unclosed single quote',\n        type: 'unclosed_quote'\n      });\n    }\n\n    if (unescapedDoubleQuotes.length % 2 !== 0) {\n      errors.push({\n        line: lineNum,\n        message: 'Unclosed double quote',\n        type: 'unclosed_quote'\n      });\n    }\n\n    // Check 3: Invalid key-value syntax\n    // A line that looks like it should be a key-value pair but isn't\n    if (!trimmedLine.startsWith('-') && !trimmedLine.startsWith('#')) {\n      // Check if it has a colon followed by space (valid) or just has content\n      const colonIndex = trimmedLine.indexOf(':');\n\n      if (colonIndex === -1 && !trimmedLine.startsWith('|') && !trimmedLine.startsWith('>')) {\n        // No colon - might be a continuation or list item\n        // Check if previous line ended with | or >\n        if (i > 0) {\n          const prevTrimmed = lines[i-1].trimStart();\n          if (!prevTrimmed.endsWith('|') && !prevTrimmed.endsWith('>') &&\n              !prevTrimmed.startsWith('-') && prevTrimmed !== '') {\n            // This might be an error - standalone value without key\n            // But it could also be a multiline continuation\n          }\n        }\n      } else if (colonIndex > 0) {\n        // Has colon - check for valid key-value format\n        const key = trimmedLine.substring(0, colonIndex);\n        const afterColon = trimmedLine.substring(colonIndex + 1);\n\n        // Key should not have special characters at the start\n        if (key.match(/^[\\[\\]{},]/)) {\n          errors.push({\n            line: lineNum,\n            message: 'Invalid key: starts with special character',\n            type: 'invalid_key_value'\n          });\n        }\n\n        // Value after colon should have space if not empty\n        if (afterColon !== '' && !afterColon.startsWith(' ') &&\n            !afterColon.startsWith('\\t')) {\n          errors.push({\n            line: lineNum,\n            message: 'Missing space after colon in key-value pair',\n            type: 'invalid_key_value'\n          });\n        }\n      }\n    }\n\n    // Check 4: List formatting errors\n    if (trimmedLine.startsWith('-')) {\n      // List item should have space after dash (unless empty)\n      if (trimmedLine.length > 1 && trimmedLine[1] !== ' ' && trimmedLine[1] !== '\\t') {\n        errors.push({\n          line: lineNum,\n          message: 'List item should have space after dash',\n          type: 'list_format'\n        });\n      }\n    }\n\n    // Check 5: Indentation jump check\n    if (currentIndent > prevIndent + 2 && prevIndent !== 0) {\n      // Indentation jumped by more than 2 spaces\n      errors.push({\n        line: lineNum,\n        message: `Unexpected indentation increase (from ${prevIndent} to ${currentIndent})`,\n        type: 'indentation'\n      });\n    }\n\n    prevIndent = currentIndent;\n  }\n\n  return {\n    valid: errors.length === 0,\n    errors\n  };\n}\n\n// ==========================================\n// REFERENCE PARSER (Using Built-in or eval-based approach)\n// ==========================================\n\n// Since we want to compare with a \"proper\" parser, let's use a simple\n// approach to test if YAML is syntactically valid by trying to parse\n// common structures.\n\nfunction referenceYamlValidator(content: string): { valid: boolean; error?: string } {\n  // For a proper comparison, we'll use a basic parser that catches real YAML errors\n  // In a real scenario, we'd use js-yaml or similar\n\n  try {\n    // Simple structural checks that a real parser would catch\n    const lines = content.split('\\n');\n\n    for (let i = 0; i < lines.length; i++) {\n      const line = lines[i];\n      const trimmed = line.trimStart();\n\n      if (trimmed === '' || trimmed.startsWith('#')) continue;\n\n      // Check for duplicate keys (basic check)\n      // Check for invalid flow syntax\n      // Check for proper escaping\n\n      // Tabs are technically valid in YAML but often cause issues\n      if (line.includes('\\t') && !line.match(/:\\s*[\"'].*\\t.*[\"']/)) {\n        // Tab in indentation is problematic\n        const indent = line.match(/^[\\t ]+/);\n        if (indent && indent[0].includes('\\t')) {\n          return { valid: false, error: `Line ${i + 1}: Tab in indentation` };\n        }\n      }\n    }\n\n    return { valid: true };\n  } catch (e: any) {\n    return { valid: false, error: e.message };\n  }\n}\n\n// ==========================================\n// TEST CASES\n// ==========================================\n\ninterface TestCase {\n  name: string;\n  yaml: string;\n  expectedValid: boolean;\n  errorType?: string;\n}\n\nconst testCases: TestCase[] = [\n  // INDENTATION ERRORS\n  {\n    name: 'Valid YAML - basic',\n    yaml: `name: test\nversion: 1.0.0`,\n    expectedValid: true\n  },\n  {\n    name: 'Valid YAML - nested',\n    yaml: `config:\n  database:\n    host: localhost\n    port: 5432`,\n    expectedValid: true\n  },\n  {\n    name: 'Indentation error - inconsistent',\n    yaml: `config:\n  name: test\n   version: 1.0.0`,\n    expectedValid: false,\n    errorType: 'indentation'\n  },\n  {\n    name: 'Indentation error - tabs',\n    yaml: `config:\n\\tname: test`,\n    expectedValid: false,\n    errorType: 'indentation'\n  },\n\n  // UNCLOSED QUOTES\n  {\n    name: 'Unclosed single quote',\n    yaml: `name: 'unterminated`,\n    expectedValid: false,\n    errorType: 'unclosed_quote'\n  },\n  {\n    name: 'Unclosed double quote',\n    yaml: `name: \"unterminated`,\n    expectedValid: false,\n    errorType: 'unclosed_quote'\n  },\n  {\n    name: 'Valid quoted string',\n    yaml: `name: \"valid string\"`,\n    expectedValid: true\n  },\n  {\n    name: 'Valid single quoted string',\n    yaml: `name: 'valid string'`,\n    expectedValid: true\n  },\n\n  // INVALID KEY-VALUE SYNTAX\n  {\n    name: 'Missing space after colon',\n    yaml: `name:value`,\n    expectedValid: false,\n    errorType: 'invalid_key_value'\n  },\n  {\n    name: 'Valid key-value',\n    yaml: `name: value`,\n    expectedValid: true\n  },\n  {\n    name: 'Key with special char start',\n    yaml: `[invalid: key`,\n    expectedValid: false,\n    errorType: 'invalid_key_value'\n  },\n\n  // EMPTY FILES\n  {\n    name: 'Empty file',\n    yaml: ``,\n    expectedValid: true // Empty YAML is valid\n  },\n  {\n    name: 'Only comments',\n    yaml: `# This is a comment\n# Another comment`,\n    expectedValid: true\n  },\n  {\n    name: 'Only whitespace',\n    yaml: `\n\n`,\n    expectedValid: true\n  },\n\n  // LIST FORMATTING\n  {\n    name: 'Valid list',\n    yaml: `items:\n  - first\n  - second\n  - third`,\n    expectedValid: true\n  },\n  {\n    name: 'List without space after dash',\n    yaml: `items:\n  -first\n  -second`,\n    expectedValid: false,\n    errorType: 'list_format'\n  },\n  {\n    name: 'Nested list valid',\n    yaml: `items:\n  - name: item1\n    value: 1\n  - name: item2\n    value: 2`,\n    expectedValid: true\n  },\n\n  // EDGE CASES - potential false positives/negatives\n  {\n    name: 'Colon in string value (valid)',\n    yaml: `url: http://example.com`,\n    expectedValid: true\n  },\n  {\n    name: 'Multiline string indicator',\n    yaml: `description: |\n  This is a long\n  multiline string`,\n    expectedValid: true\n  },\n  {\n    name: 'Flow sequence (valid)',\n    yaml: `items: [a, b, c]`,\n    expectedValid: true\n  },\n  {\n    name: 'Complex nested structure',\n    yaml: `root:\n  level1:\n    level2:\n      level3:\n        key: value`,\n    expectedValid: true\n  },\n];\n\n// ==========================================\n// RUN EXPERIMENT\n// ==========================================\n\nconsole.log('='.repeat(60));\nconsole.log('HYPOTHESIS EXPERIMENT: HYP-001');\nconsole.log('Custom YAML Validator vs Reference Parser');\nconsole.log('='.repeat(60));\nconsole.log();\n\nlet customCorrect = 0;\nlet customIncorrect = 0;\nlet falsePositives: string[] = [];\nlet falseNegatives: string[] = [];\n\nfor (const testCase of testCases) {\n  const customResult = customYamlValidator(testCase.yaml);\n  const customValid = customResult.valid;\n\n  const passed = customValid === testCase.expectedValid;\n\n  if (passed) {\n    customCorrect++;\n    console.log(`[PASS] ${testCase.name}`);\n  } else {\n    customIncorrect++;\n    if (customValid && !testCase.expectedValid) {\n      falseNegatives.push(testCase.name);\n      console.log(`[FAIL - FALSE NEGATIVE] ${testCase.name}`);\n      console.log(`  Expected: INVALID, Got: VALID`);\n      console.log(`  Expected error type: ${testCase.errorType}`);\n    } else {\n      falsePositives.push(testCase.name);\n      console.log(`[FAIL - FALSE POSITIVE] ${testCase.name}`);\n      console.log(`  Expected: VALID, Got: INVALID`);\n      console.log(`  Errors found:`, customResult.errors);\n    }\n  }\n}\n\nconsole.log();\nconsole.log('='.repeat(60));\nconsole.log('SUMMARY');\nconsole.log('='.repeat(60));\nconsole.log(`Total test cases: ${testCases.length}`);\nconsole.log(`Correct: ${customCorrect}`);\nconsole.log(`Incorrect: ${customIncorrect}`);\nconsole.log(`Accuracy: ${((customCorrect / testCases.length) * 100).toFixed(1)}%`);\nconsole.log();\n\nif (falsePositives.length > 0) {\n  console.log(`False Positives (valid YAML marked as invalid):`);\n  falsePositives.forEach(fp => console.log(`  - ${fp}`));\n}\n\nif (falseNegatives.length > 0) {\n  console.log(`False Negatives (invalid YAML marked as valid):`);\n  falseNegatives.forEach(fn => console.log(`  - ${fn}`));\n}\n\nconsole.log();\nconsole.log('='.repeat(60));\nconsole.log('CONCLUSION');\nconsole.log('='.repeat(60));\n\nconst successThreshold = 0.85; // 85% accuracy threshold\nconst accuracy = customCorrect / testCases.length;\n\nif (accuracy >= successThreshold && falseNegatives.length === 0) {\n  console.log('HYPOTHESIS CONFIRMED');\n  console.log('The custom validator detected all tested syntax errors');\n  console.log('and achieved acceptable accuracy on valid YAML cases.');\n} else if (falseNegatives.length > 0) {\n  console.log('HYPOTHESIS REJECTED');\n  console.log('The custom validator FAILED to detect the following syntax errors:');\n  falseNegatives.forEach(fn => console.log(`  - ${fn}`));\n  console.log('These are errors that external parsers would catch.');\n} else {\n  console.log('HYPOTHESIS REJECTED');\n  console.log(`Accuracy (${(accuracy * 100).toFixed(1)}%) below threshold (${successThreshold * 100}%)`);\n  console.log('Too many false positives on valid YAML.');\n}\n"
