        "file_path": "/private/tmp/rp1-evals/0c034016/workspace/.rp1/work/worktrees/feature-yaml-validator-command/src/yaml/validator.test.ts",
        "content": "/**\n * Unit and integration tests for the YAML validator module.\n */\n\nimport { describe, test, expect, beforeAll, afterAll } from \"bun:test\";\nimport { validateYamlFile, validateYamlContent } from \"./validator\";\nimport type { ErrorType } from \"./types\";\nimport { unlink, writeFile, mkdir } from \"fs/promises\";\nimport { join } from \"path\";\n\nconst TEST_DIR = join(import.meta.dir, \"__test_fixtures__\");\n\ndescribe(\"validateYamlContent\", () => {\n  describe(\"valid YAML\", () => {\n    test(\"simple key-value pairs return valid result\", () => {\n      const content = `name: test\nversion: 1.0.0\nenabled: true`;\n      const result = validateYamlContent(content);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"nested structures validate correctly\", () => {\n      const content = `database:\n  host: localhost\n  port: 5432\n  credentials:\n    username: admin\n    password: secret\nsettings:\n  debug: true\n  logLevel: info`;\n      const result = validateYamlContent(content);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"list items are valid\", () => {\n      const content = `items:\n  - first\n  - second\n  - third`;\n      const result = validateYamlContent(content);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"mixed nested structures with lists\", () => {\n      const content = `services:\n  - name: api\n    port: 8080\n    endpoints:\n      - /health\n      - /status\n  - name: web\n    port: 3000`;\n      const result = validateYamlContent(content);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"quoted strings are valid\", () => {\n      const content = `message: \"Hello, World!\"\nnote: 'Single quoted'\nkey: \"Value with: colon inside\"`;\n      const result = validateYamlContent(content);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"multiline strings with pipe indicator\", () => {\n      const content = `description: |\n  This is a multiline\n  string that spans\n  multiple lines\nname: test`;\n      const result = validateYamlContent(content);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"comments are handled correctly\", () => {\n      const content = `# This is a comment\nname: test # inline comment\n# Another comment\nversion: 1.0`;\n      const result = validateYamlContent(content);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n\n    test(\"document separator is valid\", () => {\n      const content = `---\nname: test\nversion: 1.0`;\n      const result = validateYamlContent(content);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n  });\n\n  describe(\"empty file detection\", () => {\n    test(\"empty content returns EmptyFile error\", () => {\n      const result = validateYamlContent(\"\");\n      expect(result.valid).toBe(false);\n      expect(result.errors).toHaveLength(1);\n      expect(result.errors[0].type).toBe(\"EmptyFile\" as ErrorType);\n      expect(result.errors[0].message).toContain(\"empty\");\n    });\n\n    test(\"whitespace-only content treated as empty\", () => {\n      const content = \"   \\n\\t\\n   \";\n      const result = validateYamlContent(content);\n      expect(result.valid).toBe(false);\n      expect(result.errors).toHaveLength(1);\n      expect(result.errors[0].type).toBe(\"EmptyFile\" as ErrorType);\n    });\n  });\n\n  describe(\"indentation errors\", () => {\n    test(\"tab indentation is detected\", () => {\n      const content = `name: test\n\\tversion: 1.0`;\n      const result = validateYamlContent(content);\n      expect(result.valid).toBe(false);\n      expect(result.errors.some((e) => e.type === \"IndentationError\")).toBe(\n        true\n      );\n      expect(\n        result.errors.some((e) => e.message.toLowerCase().includes(\"tab\"))\n      ).toBe(true);\n    });\n\n    test(\"inconsistent indentation is detected\", () => {\n      const content = `root:\n  child1: value\n   child2: value`;\n      const result = validateYamlContent(content);\n      expect(result.valid).toBe(false);\n      expect(result.errors.some((e) => e.type === \"IndentationError\")).toBe(\n        true\n      );\n      expect(\n        result.errors.some((e) => e.message.includes(\"Inconsistent\"))\n      ).toBe(true);\n    });\n  });\n\n  describe(\"quote errors\", () => {\n    test(\"unclosed double quote is detected\", () => {\n      const content = `name: \"unclosed string\nversion: 1.0`;\n      const result = validateYamlContent(content);\n      expect(result.valid).toBe(false);\n      expect(result.errors.some((e) => e.type === \"QuoteError\")).toBe(true);\n      expect(result.errors.some((e) => e.message.includes(\"Unclosed\"))).toBe(\n        true\n      );\n    });\n\n    test(\"unclosed single quote is detected\", () => {\n      const content = `name: 'unclosed string\nversion: 1.0`;\n      const result = validateYamlContent(content);\n      expect(result.valid).toBe(false);\n      expect(result.errors.some((e) => e.type === \"QuoteError\")).toBe(true);\n    });\n  });\n\n  describe(\"syntax errors\", () => {\n    test(\"empty key in key-value pair is detected\", () => {\n      const content = `: value`;\n      const result = validateYamlContent(content);\n      expect(result.valid).toBe(false);\n      expect(result.errors.some((e) => e.type === \"SyntaxError\")).toBe(true);\n      expect(result.errors.some((e) => e.message.includes(\"Empty key\"))).toBe(\n        true\n      );\n    });\n\n    test(\"unclosed square bracket is detected\", () => {\n      const content = `items: [one, two, three`;\n      const result = validateYamlContent(content);\n      expect(result.valid).toBe(false);\n      expect(result.errors.some((e) => e.type === \"SyntaxError\")).toBe(true);\n      expect(\n        result.errors.some((e) => e.message.includes(\"square bracket\"))\n      ).toBe(true);\n    });\n\n    test(\"unclosed curly brace is detected\", () => {\n      const content = `data: {key: value`;\n      const result = validateYamlContent(content);\n      expect(result.valid).toBe(false);\n      expect(result.errors.some((e) => e.type === \"SyntaxError\")).toBe(true);\n      expect(\n        result.errors.some((e) => e.message.includes(\"curly brace\"))\n      ).toBe(true);\n    });\n  });\n\n  describe(\"list errors\", () => {\n    test(\"list item without space after dash is detected\", () => {\n      const content = `items:\n  -first\n  - second`;\n      const result = validateYamlContent(content);\n      expect(result.valid).toBe(false);\n      expect(result.errors.some((e) => e.type === \"ListError\")).toBe(true);\n      expect(\n        result.errors.some((e) => e.message.includes(\"space after the dash\"))\n      ).toBe(true);\n    });\n  });\n\n  describe(\"duplicate key detection\", () => {\n    test(\"duplicate keys at same level are detected\", () => {\n      const content = `name: first\nversion: 1.0\nname: duplicate`;\n      const result = validateYamlContent(content);\n      expect(result.valid).toBe(false);\n      expect(result.errors.some((e) => e.type === \"DuplicateKeyError\")).toBe(\n        true\n      );\n      expect(result.errors.some((e) => e.message.includes(\"Duplicate\"))).toBe(\n        true\n      );\n    });\n\n    test(\"same keys at different indentation levels are allowed\", () => {\n      const content = `parent:\n  name: child_name\nname: parent_name`;\n      const result = validateYamlContent(content);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toHaveLength(0);\n    });\n  });\n\n  describe(\"error location reporting\", () => {\n    test(\"error includes line number\", () => {\n      const content = `line1: ok\nline2: ok\nline3: \"unclosed`;\n      const result = validateYamlContent(content);\n      expect(result.valid).toBe(false);\n      expect(result.errors[0].line).toBe(3);\n    });\n  });\n});\n\ndescribe(\"validateYamlFile\", () => {\n  beforeAll(async () => {\n    await mkdir(TEST_DIR, { recursive: true });\n  });\n\n  afterAll(async () => {\n    try {\n      const files = [\"valid.yaml\", \"invalid.yaml\", \"empty.yaml\"];\n      await Promise.all(\n        files.map((f) => unlink(join(TEST_DIR, f)).catch(() => {}))\n      );\n      await unlink(TEST_DIR).catch(() => {});\n    } catch {\n      // Ignore cleanup errors\n    }\n  });\n\n  test(\"non-existent file returns FileNotFound error\", async () => {\n    const result = await validateYamlFile(\"/nonexistent/path/file.yaml\");\n    expect(result.valid).toBe(false);\n    expect(result.errors).toHaveLength(1);\n    expect(result.errors[0].type).toBe(\"FileNotFound\" as ErrorType);\n    expect(result.errors[0].message).toContain(\"not found\");\n  });\n\n  test(\"valid file returns valid result\", async () => {\n    const filePath = join(TEST_DIR, \"valid.yaml\");\n    await writeFile(filePath, \"name: test\\nversion: 1.0\\n\");\n\n    const result = await validateYamlFile(filePath);\n    expect(result.valid).toBe(true);\n    expect(result.errors).toHaveLength(0);\n    expect(result.filePath).toBe(filePath);\n  });\n\n  test(\"invalid file returns errors with file path\", async () => {\n    const filePath = join(TEST_DIR, \"invalid.yaml\");\n    await writeFile(filePath, 'key: \"unclosed\\n');\n\n    const result = await validateYamlFile(filePath);\n    expect(result.valid).toBe(false);\n    expect(result.errors.length).toBeGreaterThan(0);\n    expect(result.filePath).toBe(filePath);\n  });\n\n  test(\"empty file returns EmptyFile error\", async () => {\n    const filePath = join(TEST_DIR, \"empty.yaml\");\n    await writeFile(filePath, \"\");\n\n    const result = await validateYamlFile(filePath);\n    expect(result.valid).toBe(false);\n    expect(result.errors[0].type).toBe(\"EmptyFile\" as ErrorType);\n  });\n});\n\ndescribe(\"CLI integration tests\", () => {\n  beforeAll(async () => {\n    await mkdir(TEST_DIR, { recursive: true });\n  });\n\n  afterAll(async () => {\n    try {\n      const files = [\"cli_valid.yaml\", \"cli_invalid.yaml\"];\n      await Promise.all(\n        files.map((f) => unlink(join(TEST_DIR, f)).catch(() => {}))\n      );\n    } catch {\n      // Ignore cleanup errors\n    }\n  });\n\n  const CLI_PATH = join(import.meta.dir, \"..\", \"validate-yaml.ts\");\n\n  test(\"CLI success flow returns exit code 0\", async () => {\n    const filePath = join(TEST_DIR, \"cli_valid.yaml\");\n    await writeFile(filePath, \"name: test\\nversion: 1.0\\n\");\n\n    const proc = Bun.spawn([\"bun\", \"run\", CLI_PATH, filePath], {\n      stdout: \"pipe\",\n      stderr: \"pipe\",\n    });\n    await proc.exited;\n    expect(proc.exitCode).toBe(0);\n\n    const stdout = await new Response(proc.stdout).text();\n    expect(stdout).toContain(\"Valid:\");\n  });\n\n  test(\"CLI failure flow returns exit code 1 for invalid YAML\", async () => {\n    const filePath = join(TEST_DIR, \"cli_invalid.yaml\");\n    await writeFile(filePath, 'key: \"unclosed\\n');\n\n    const proc = Bun.spawn([\"bun\", \"run\", CLI_PATH, filePath], {\n      stdout: \"pipe\",\n      stderr: \"pipe\",\n    });\n    await proc.exited;\n    expect(proc.exitCode).toBe(1);\n\n    const stdout = await new Response(proc.stdout).text();\n    expect(stdout).toContain(\"Invalid:\");\n  });\n\n  test(\"CLI with missing file returns exit code 1\", async () => {\n    const proc = Bun.spawn(\n      [\"bun\", \"run\", CLI_PATH, \"/nonexistent/file.yaml\"],\n      {\n        stdout: \"pipe\",\n        stderr: \"pipe\",\n      }\n    );\n    await proc.exited;\n    expect(proc.exitCode).toBe(1);\n\n    const stderr = await new Response(proc.stderr).text();\n    expect(stderr).toContain(\"File not found\");\n  });\n\n  test(\"CLI with no args shows usage error\", async () => {\n    const proc = Bun.spawn([\"bun\", \"run\", CLI_PATH], {\n      stdout: \"pipe\",\n      stderr: \"pipe\",\n    });\n    await proc.exited;\n    expect(proc.exitCode).toBe(1);\n\n    const stderr = await new Response(proc.stderr).text();\n    expect(stderr).toContain(\"No file path provided\");\n  });\n});\n"
