n      const indentDiff = currentIndent - parentIndent;\n\n      // Standard YAML indentation is typically 2 spaces\n      // But odd indentation at non-standard positions is problematic\n      if (indentDiff !== 2 && indentDiff !== 0 && currentIndent !== parentIndent) {\n        // Check if this is a valid indent level we've seen before\n        const validIndent = indentStack.includes(currentIndent);\n        if (!validIndent && indentDiff !== 2) {\n          errors.push({\n            line: lineNum,\n            message: `Inconsistent indentation: expected ${parentIndent + 2} spaces, got ${currentIndent}`,\n            type: 'indentation'\n          });\n        }\n      }\n\n      indentStack.push(currentIndent);\n    } else {\n      // Reset to root level\n      indentStack.length = 1;\n      indentStack[0] = 0;\n    }\n\n    // Check for unclosed quotes\n    const unescapedSingleQuotes = trimmedLine.replace(/\\\\'/g, '').match(/'/g) || [];\n    const unescapedDoubleQuotes = trimmedLine.replace(/\\\\\"/g, '').match(/\"/g) || [];\n\n    if (unescapedSingleQuotes.length % 2 !== 0) {\n      errors.push({\n        line: lineNum,\n        message: 'Unclosed single quote',\n        type: 'unclosed_quote'\n      });\n    }\n\n    if (unescapedDoubleQuotes.length % 2 !== 0) {\n      errors.push({\n        line: lineNum,\n        message: 'Unclosed double quote',\n        type: 'unclosed_quote'\n      });\n    }\n\n    // Check key-value syntax\n    if (!trimmedLine.startsWith('-') && !trimmedLine.startsWith('#') &&\n        !trimmedLine.startsWith('|') && !trimmedLine.startsWith('>')) {\n      const colonIndex = trimmedLine.indexOf(':');\n\n      if (colonIndex > 0) {\n        const afterColon = trimmedLine.substring(colonIndex + 1);\n\n        // Value after colon should have space if not empty\n        if (afterColon !== '' && !afterColon.startsWith(' ') && !afterColon.startsWith('\\t')) {\n          errors.push({\n            line: lineNum,\n            message: 'Missing space after colon in key-value pair',\n            type: 'invalid_key_value'\n          });\n        }\n\n        // Check for invalid key characters\n        const key = trimmedLine.substring(0, colonIndex);\n        if (key.match(/^[\\[\\]{},]/)) {\n          errors.push({\n            line: lineNum,\n            message: 'Invalid key: starts with special character',\n            type: 'invalid_key_value'\n          });\n        }\n      }\n    }\n\n    // Check list formatting\n    if (trimmedLine.startsWith('-')) {\n      if (trimmedLine.length > 1 && trimmedLine[1] !== ' ' && trimmedLine[1] !== '\\t') {\n        errors.push({\n          line: lineNum,\n          message: 'List item should have space after dash',\n          type: 'list_format'\n        });\n      }\n    }\n  }\n\n  return {\n    valid: errors.length === 0,\n    errors\n  };\n}\n\n// ==========================================\n// REFERENCE: JS-YAML PARSER\n// ==========================================\n\nfunction jsYamlValidate(content: string): { valid: boolean; error?: string } {\n  try {\n    parseYaml(content);\n    return { valid: true };\n  } catch (e: any) {\n    return { valid: false, error: e.message };\n  }\n}\n\n// ==========================================\n// COMPREHENSIVE TEST CASES\n// ==========================================\n\ninterface TestCase {\n  name: string;\n  yaml: string;\n  category: string;\n}\n\nconst testCases: TestCase[] = [\n  // VALID YAML\n  { name: 'Valid - basic', category: 'valid', yaml: `name: test\\nversion: 1.0.0` },\n  { name: 'Valid - nested', category: 'valid', yaml: `config:\\n  db:\\n    host: localhost` },\n  { name: 'Valid - list', category: 'valid', yaml: `items:\\n  - one\\n  - two\\n  - three` },\n  { name: 'Valid - empty', category: 'valid', yaml: `` },\n  { name: 'Valid - comments only', category: 'valid', yaml: `# comment\\n# another` },\n  { name: 'Valid - quoted colon', category: 'valid', yaml: `url: \"http://example.com\"` },\n  { na