// ==========================================
// CUSTOM YAML VALIDATOR - Corrected Version
// ==========================================

interface ValidationError {
  line: number;
  message: string;
  type: string;
  severity: 'error' | 'warning';
}

interface ValidationResult {
  valid: boolean;
  errors: ValidationError[];
  warnings: ValidationError[];
}

function customYamlValidator(content: string): ValidationResult {
  const errors: ValidationError[] = [];
  const warnings: ValidationError[] = [];
  const lines = content.split('\n');

  // Track indentation
  const indentStack: number[] = [0];

  for (let i = 0; i < lines.length; i++) {
    const lineNum = i + 1;
    const line = lines[i];
    const trimmedLine = line.trimStart();

    // Skip empty lines and comments
    if (trimmedLine === '' || trimmedLine.startsWith('#')) {
      continue;
    }

    // Get leading whitespace
    const leadingWhitespace = line.match(/^[\s]*/)?.[0] || '';
    const currentIndent = leadingWhitespace.replace(/\t/g, '').length;

    // Check for tabs in indentation - this IS an error per YAML spec
    if (leadingWhitespace.includes('\t')) {
      errors.push({
        line: lineNum,
        message: 'Tab character in indentation (YAML spec forbids tabs for indentation)',
        type: 'indentation',
        severity: 'error'
      });
    }

    // Indentation consistency check
    if (currentIndent > 0 && !leadingWhitespace.includes('\t')) {
      const parentIndent = indentStack[indentStack.length - 1] || 0;

      if (currentIndent > parentIndent) {
        // Going deeper - should be exactly +2 (standard) or consistent increment
        const diff = currentIndent - parentIndent;
        if (diff !== 2 && diff !== 1) { // Allow 1 or 2 space increments
          // Check if this could be returning to a previous level
          const knownLevel = indentStack.includes(currentIndent);
          if (!knownLevel) {
            errors.push({
              line: lineNum,
              message: `Bad indentation: ${currentIndent} spaces (expected ${parentIndent + 2} or previous level)`,
              type: 'indentation',
              severity: 'error'
            });
          }
        }
        indentStack.push(currentIndent);
      } else if (currentIndent < parentIndent) {
        // Coming back up - must match a previous level
        while (indentStack.length > 1 && indentStack[indentStack.length - 1] > currentIndent) {
          indentStack.pop();
        }
        if (indentStack[indentStack.length - 1] !== currentIndent && currentIndent !== 0) {
          if (!indentStack.includes(currentIndent)) {
            errors.push({
              line: lineNum,
              message: `Bad indentation: ${currentIndent} spaces doesn't match any previous level`,
              type: 'indentation',
              severity: 'error'
            });
          }
        }
      }
    } else if (currentIndent === 0) {
      indentStack.length = 1;
    }

    // Quote checking - must handle multiline strings properly
    // Only check quotes if not in a multiline block
    if (!trimmedLine.startsWith('|') && !trimmedLine.startsWith('>')) {
      let inSingleQuote = false;
      let inDoubleQuote = false;
      let prevChar = '';

      for (let j = 0; j < trimmedLine.length; j++) {
        const char = trimmedLine[j];

        // Handle escapes
        if (prevChar !== '\\') {
          if (char === "'" && !inDoubleQuote) {
            inSingleQuote = !inSingleQuote;
          } else if (char === '"' && !inSingleQuote) {
            inDoubleQuote = !inDoubleQuote;
          }
        }
        prevChar = char;
      }

      if (inSingleQuote) {
        errors.push({
          line: lineNum,
          message: 'Unclosed single quote',
          type: 'unclosed_quote',
          severity: 'error'
        });
      }
      if (inDoubleQuote) {
        errors.push({
          line: lineNum,
          message: 'Unclosed double quote',
          type: 'unclosed_quote',
          severity: 'error'
        });
      }
    }

    // Key-value format - NOTE: YAML actually allows key:value (no space)
    // but it's bad practice. We'll make this a WARNING not an error.
    if (!trimmedLine.startsWith('-') && !trimmedLine.startsWith('#') &&
        !trimmedLine.startsWith('|') && !trimmedLine.startsWith('>') &&
        !trimmedLine.startsWith('[') && !trimmedLine.startsWith('{')) {
      const colonIndex = trimmedLine.indexOf(':');
      if (colonIndex > 0) {
        const afterColon = trimmedLine.substring(colonIndex + 1);
        if (afterColon !== '' && !afterColon.startsWith(' ') && !afterColon.startsWith('\t')) {
          warnings.push({
            line: lineNum,
            message: 'No space after colon (valid but discouraged style)',
            type: 'style',
            severity: 'warning'
          });
        }
      }
    }

    // List format - YAML actually allows "-item" (no space) but it's parsed as string "-item"
    // This is a subtle difference - we'll warn but not error
    if (trimmedLine.startsWith('-') && trimmedLine.length > 1 &&
        trimmedLine[1] !== ' ' && trimmedLine[1] !== '\t') {
      warnings.push({
        line: lineNum,
        message: 'No space after dash (valid but may not be intended as list)',
        type: 'style',
        severity: 'warning'
      });
    }
  }

  return {
    valid: errors.length === 0,
    errors,
    warnings
  };
}

