/**
 * CLI entry point for YAML validation command.
 *
 * Usage: bun run validate-yaml <filepath>
 *
 * Exit codes:
 *   0 - Validation successful
 *   1 - Validation failed or error occurred
 */

import { validateYamlFile } from "./yaml/validator";

async function main(): Promise<void> {
  const args = process.argv.slice(2);

  if (args.length === 0) {
    console.error("Error: No file path provided");
    console.error("Usage: bun run validate-yaml <filepath>");
    process.exit(1);
  }

  const filePath = args[0];
  const result = await validateYamlFile(filePath);

  if (result.valid) {
    console.log(`Valid: ${result.filePath}`);
    process.exit(0);
  }

  if (
    result.errors.length > 0 &&
    result.errors[0].type === "FileNotFound"
  ) {
    console.error(`Error: File not found: ${filePath}`);
    process.exit(1);
  }

  if (
    result.errors.length > 0 &&
    result.errors[0].type === "FileReadError"
  ) {
    console.error(`Error: ${result.errors[0].message}`);
    process.exit(1);
  }

  console.log(`Invalid: ${result.filePath}`);
  for (const error of result.errors) {
    const lineInfo = error.line > 0 ? `Line ${error.line}: ` : "";
    console.log(`  ${lineInfo}${error.message}`);
  }
  process.exit(1);
}

main();

/**
 * Unit and integration tests for the YAML validator module.
 */

import { describe, test, expect, beforeAll, afterAll } from "bun:test";
import { validateYamlFile, validateYamlContent } from "./validator";
import type { ErrorType } from "./types";
import { unlink, writeFile, mkdir } from "fs/promises";
import { join } from "path";

const TEST_DIR = join(import.meta.dir, "__test_fixtures__");

describe("validateYamlContent", () => {
  describe("valid YAML", () => {
    test("simple key-value pairs return valid result", () => {
      const content = `name: test
version: 1.0.0
enabled: true`;
      const result = validateYamlContent(content);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("nested structures validate correctly", () => {
      const content = `database:
  host: localhost
  port: 5432
  credentials:
    username: admin
    password: secret
settings:
  debug: true
  logLevel: info`;
      const result = validateYamlContent(content);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("list items are valid", () => {
      const content = `items:
  - first
  - second
  - third`;
      const result = validateYamlContent(content);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("mixed nested structures with lists", () => {
      const content = `services:
  - name: api
    port: 8080
    endpoints:
      - /health
      - /status
  - name: web
    port: 3000`;
      const result = validateYamlContent(content);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("quoted strings are valid", () => {
      const content = `message: "Hello, World!"
note: 'Single quoted'
key: "Value with: colon inside"`;
      const result = validateYamlContent(content);
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("multiline strings with pipe indicator", () => {
      const content = `description: |
  This is a multiline
  string that spans
  multiple lines
name: test`;
