    try {
      const files = ["valid.yaml", "invalid.yaml", "empty.yaml"];
      await Promise.all(
        files.map((f) => unlink(join(TEST_DIR, f)).catch(() => {}))
      );
      await unlink(TEST_DIR).catch(() => {});
    } catch {
      // Ignore cleanup errors
    }
  });

  test("non-existent file returns FileNotFound error", async () => {
    const result = await validateYamlFile("/nonexistent/path/file.yaml");
    expect(result.valid).toBe(false);
    expect(result.errors).toHaveLength(1);
    expect(result.errors[0].type).toBe("FileNotFound" as ErrorType);
    expect(result.errors[0].message).toContain("not found");
  });

  test("valid file returns valid result", async () => {
    const filePath = join(TEST_DIR, "valid.yaml");
    await writeFile(filePath, "name: test\nversion: 1.0\n");

    const result = await validateYamlFile(filePath);
    expect(result.valid).toBe(true);
    expect(result.errors).toHaveLength(0);
    expect(result.filePath).toBe(filePath);
  });

  test("invalid file returns errors with file path", async () => {
    const filePath = join(TEST_DIR, "invalid.yaml");
    await writeFile(filePath, 'key: "unclosed\n');

    const result = await validateYamlFile(filePath);
    expect(result.valid).toBe(false);
    expect(result.errors.length).toBeGreaterThan(0);
    expect(result.filePath).toBe(filePath);
  });

  test("empty file returns EmptyFile error", async () => {
